// Destinos e limites. notionDataSourceId = database Teardowns (mesmo do collector).
// NOTA: o modelo de IA agora vem do dropdown do community node OpenRouter no SUB
// (google/gemini-2.5-flash). openrouterModel aqui nao e mais lido. Ver DESIGN.md / decisions 2026-09-02.
return [{ json: {
  notionDataSourceId: "YOUR_NOTION_DATA_SOURCE_ID",
  telegramChatId: "223199474",
  maxAdsAnalisados: 4,
  maxPagesPorRun: 20
} }];

// 1 item por pagina To do. Embrulha { page, cfg } pro sub.
const cfg = $('Configuracao').first().json;
return $input.all().map((item) => ({ json: { page: item.json, cfg } }));

const r = $input.all().map((i) => i.json);
const ok = r.filter((x) => x && !x.erro);
const err = r.filter((x) => x && x.erro);
const linhas = ok.slice(0, 12).map((x) => `- ${x.brand}`).join('\n');
const texto = ok.length
  ? `Meta Ad Library - teardowns\n${ok.length} pronto(s)${err.length ? `, ${err.length} com erro` : ''}:\n\n${linhas}`
  : `Meta Ad Library - teardowns\nNada novo${err.length ? ` (${err.length} com erro)` : ''}.`;
return [{ json: { texto, ok: ok.length, err: err.length } }];
